<?php
require_once __DIR__ . '/../includes/auth.php'; require_login('admin'); $error = null;
if ($_SERVER['REQUEST_METHOD'] === 'POST') { verify_csrf(); $action = $_POST['action'] ?? ''; try { if ($action === 'add') { $statement = db()->prepare('INSERT INTO leave_types (name, description, default_days, color) VALUES (?, ?, ?, ?)'); $statement->execute([trim($_POST['name']), trim($_POST['description']), (float) $_POST['default_days'], $_POST['color']]); flash('success', 'Leave type added.'); } elseif ($action === 'toggle') { $statement = db()->prepare('UPDATE leave_types SET is_active = NOT is_active WHERE id = ?'); $statement->execute([(int) $_POST['id']]); flash('success', 'Leave type status updated.'); } } catch (PDOException $exception) { $error = 'That leave type already exists.'; } }
$types = db()->query('SELECT * FROM leave_types ORDER BY is_active DESC, name')->fetchAll(); $pageTitle = 'Leave types'; require __DIR__ . '/../includes/header.php';
?><div class="page-content"><div class="detail-heading"><div><span class="eyebrow">Administration / Policy</span><h2>Leave types</h2><p class="muted mb-0">Define the options employees can request.</p></div></div><div class="content-grid"><section class="panel"><div class="panel-heading"><h3>Current leave types</h3></div><table class="table"><thead><tr><th>Type</th><th>Default allowance</th><th>Status</th><th></th></tr></thead><tbody><?php foreach ($types as $type): ?><tr><td><strong style="color:<?= e($type['color']) ?>">&#9679; <?= e($type['name']) ?></strong><br><small class="muted"><?= e($type['description']) ?></small></td><td><?= e((string) $type['default_days']) ?> days</td><td><span class="status <?= $type['is_active'] ? 'status-approved' : 'status-cancelled' ?>"><?= $type['is_active'] ? 'Active' : 'Inactive' ?></span></td><td><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?= $type['id'] ?>"><button class="btn btn-sm btn-outline-dark" type="submit">Toggle</button></form></td></tr><?php endforeach; ?></tbody></table></section><section class="panel"><div class="panel-heading"><h3>Add a leave type</h3></div><?php if ($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?><form method="post" class="stack-form"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="add"><label>Name<input name="name" placeholder="Parental leave" required></label><label>Description<textarea name="description" placeholder="What is this leave for?"></textarea></label><label>Default days<input type="number" name="default_days" step="0.5" value="5" required></label><label>Accent color<input type="color" name="color" value="#3658d6" class="form-control form-control-color"></label><button class="btn btn-primary" type="submit">Add leave type</button></form></section></div></div><?php require __DIR__ . '/../includes/footer.php'; ?>
